ST.xhtml:
// =============================================================================
// 场景：自定义协议帧字节 buffer 含 hex 字符（如 '1A' 表示寄存器值 0x1A）。
//       PLC 端逐字节读 buffer，把两个相邻 hex 字符（高/低 nibble）合成字节
//       值，写入控制变量。
// 价值：替代手写 'IF asc >= 30 AND asc <= 39 THEN ...' 五分支判断；单调
//       用、识别大小写、出错统一返回 255 便于判错。
// 验证步骤：
//   1. 登录后 bHexHighChar = 0x31 ('1')，bHexLowChar = 0x41 ('A')。
//   2. 写 bParseRequest := TRUE 触发一次。
//   3. 观察 bHighNibValue = 1，bLowNibValue = 10，bAssembledByte = 0x1A = 26，
//      bParseError = FALSE。
//   4. 把 bHexHighChar 改成 0x47（'G'，非 hex），再触发：bHighNibValue = 255，
//      bParseError = TRUE——印证 §3 错误码 255。
//   5. 大小写不敏感：把 bHexLowChar 从 0x41 改成 0x61（'a'），结果一致。
// =============================================================================

IF bParseRequest THEN
    // 单次调用：两次拆 nibble 再合成
    bHighNibValue := HEXASCNIBBLE_TO_BYTE(asc := bHexHighChar);
    bLowNibValue  := HEXASCNIBBLE_TO_BYTE(asc := bHexLowChar);

    // 判错：任一 nibble = 255 即失败
    bParseError := (bHighNibValue = 255) OR (bLowNibValue = 255);

    IF NOT bParseError THEN
        // 高 nibble 左移 4 位 + 低 nibble = 完整字节
        bAssembledByte := SHL(bHighNibValue, 4) OR bLowNibValue;
    END_IF;

    bParseRequest := FALSE;
END_IF;
